"use client";
import * as React from "react";
import * as THREE from "three";
import { useFrame } from "@react-three/fiber";
import { View, PerspectiveCamera } from "@react-three/drei";
import { cn, seededUnit } from "@/lib/pixel3d";
import { useStickerCanvas } from "@/components/ui/three/sticker-canvas";
import { VoxelSticker } from "@/components/ui/three/voxel-sticker";
import { PatternSVG } from "@/components/ui/three/sticker-3d";
import { patterns, type PatternName, type PixelPattern } from "@/components/ui/three/patterns";

/**
 * StickerScene — the landing-page showpiece: a hero-sized view where a loose cluster of voxel
 * stickers floats at different depths, drifts, parallaxes toward the pointer and peels when
 * hovered. Children sit in the clear middle (the stickers keep out of their way).
 * Before the shared canvas is ready it shows the same cluster as flat SVG stickers.
 *
 *   <StickerScene className="h-[520px]">
 *     <h1>Hack the pixel</h1>
 *   </StickerScene>
 */
export type SceneSticker =
  | PatternName
  | PixelPattern
  | { pattern: PatternName | PixelPattern; colors?: Record<string, string> };

export interface StickerSceneProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Patterns to scatter; they repeat to fill `density`. Defaults to the built-in set. */
  stickers?: readonly SceneSticker[];
  /** How many stickers float in the cluster. Default 14 (1–40). */
  density?: number;
  /** Accessible name for the decorative scene. Omit to hide it from screen readers. */
  label?: string;
}

const DEFAULT_STICKERS: PatternName[] = ["heart", "star", "bolt", "trophy", "rocket", "coffee", "ghost", "check", "pixel"];
const CAM_Z = 14;
const FOV = 35;
const TAN = Math.tan((FOV * Math.PI) / 360);
/** Round for SSR-stable inline styles. */
const r2 = (n: number) => Math.round(n * 100) / 100;

interface Placed {
  pattern: PixelPattern;
  colors?: Record<string, string>;
  nx: number;
  ny: number;
  z: number;
  scale: number;
  phase: number;
  tilt: number;
}

function resolve(s: SceneSticker): { pattern: PixelPattern; colors?: Record<string, string> } {
  if (typeof s === "string") return { pattern: patterns[s as PatternName] };
  if (Array.isArray(s)) return { pattern: s as PixelPattern };
  const o = s as { pattern: PatternName | PixelPattern; colors?: Record<string, string> };
  return { pattern: typeof o.pattern === "string" ? patterns[o.pattern as PatternName] : o.pattern, colors: o.colors };
}

/** A deterministic loose cluster: a jittered sunflower spiral, kept out of the centre when there's content. */
function layout(stickers: readonly SceneSticker[], n: number, clearCentre: boolean): Placed[] {
  const out: Placed[] = [];
  for (let i = 0; i < n; i++) {
    const u = (k: string) => seededUnit(`scene-${i}-${k}`);
    const base = Math.sqrt((i + 0.5) / n);
    const r = clearCentre ? 0.74 + 0.26 * base : 0.12 + 0.88 * base;
    const a = i * 2.39996 + u("a") * 0.5;
    const z = -6 + (u("z") + 1) * 3.2; // -6 … 0.4
    out.push({
      ...resolve(stickers[i % stickers.length]),
      nx: Math.cos(a) * Math.min(1, r + u("r") * 0.06),
      ny: Math.sin(a) * Math.min(1, r + u("r2") * 0.06),
      z,
      scale: 0.24 + (u("s") + 1) * 0.06,
      phase: (u("p") + 1) * Math.PI,
      tilt: u("t") * 0.35,
    });
  }
  return out.sort((p, q) => p.z - q.z);
}

function useReducedMotion() {
  const [reduce, setReduce] = React.useState(false);
  React.useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduce(mq.matches);
    const on = () => setReduce(mq.matches);
    mq.addEventListener("change", on);
    return () => mq.removeEventListener("change", on);
  }, []);
  return reduce;
}

export function StickerScene({
  stickers = DEFAULT_STICKERS,
  density = 14,
  label,
  className,
  children,
  ...props
}: StickerSceneProps) {
  const { ready } = useStickerCanvas();
  const reduce = useReducedMotion();
  const box = React.useRef<HTMLDivElement>(null);
  const n = Math.max(1, Math.min(40, Math.round(density)));
  const hasContent = React.Children.count(children) > 0;
  const placed = React.useMemo(
    () => layout(stickers.length ? stickers : DEFAULT_STICKERS, n, hasContent),
    [stickers, n, hasContent]
  );

  return (
    <div
      ref={box}
      data-slot="sticker-scene"
      className={cn("relative h-[480px] w-full", className)}
      {...props}
    >
      <div
        className="absolute inset-0"
        role={label ? "img" : undefined}
        aria-label={label}
        aria-hidden={label ? undefined : true}
      >
        {!ready &&
          placed.map((p, i) => {
            const size = ((5.2 * p.scale) / (2 * (CAM_Z - p.z) * TAN)) * 100;
            return (
              <div
                key={i}
                className="absolute aspect-square"
                style={{
                  left: `${r2(50 + p.nx * 45)}%`,
                  top: `${r2(50 - p.ny * 42)}%`,
                  height: `${r2(size)}%`,
                  transform: `translate(-50%, -50%) rotate(${r2((-p.tilt * 180) / Math.PI)}deg)`,
                }}
              >
                <PatternSVG pattern={p.pattern} colors={p.colors} className="size-full" />
              </div>
            );
          })}
        {ready && (
          <View className="pointer-events-none absolute inset-0">
            <SceneContent placed={placed} box={box} reduce={reduce} />
          </View>
        )}
      </div>
      {hasContent && <div className="relative z-10 flex size-full items-center justify-center">{children}</div>}
    </div>
  );
}

const v3 = new THREE.Vector3();

function SceneContent({
  placed,
  box,
  reduce,
}: {
  placed: Placed[];
  box: React.RefObject<HTMLDivElement | null>;
  reduce: boolean;
}) {
  const groups = React.useRef<(THREE.Group | null)[]>([]);
  const cam = React.useRef<THREE.PerspectiveCamera>(null);
  const pointer = React.useRef<{ x: number; y: number } | null>(null);
  const [hovered, setHovered] = React.useState(-1);
  const hoveredRef = React.useRef(-1);

  React.useEffect(() => {
    const move = (e: PointerEvent) => void (pointer.current = { x: e.clientX, y: e.clientY });
    const leave = () => void (pointer.current = null);
    window.addEventListener("pointermove", move, { passive: true });
    document.documentElement.addEventListener("pointerleave", leave);
    return () => {
      window.removeEventListener("pointermove", move);
      document.documentElement.removeEventListener("pointerleave", leave);
    };
  }, []);

  useFrame((state, dt) => {
    const el = box.current;
    const c = cam.current;
    if (!el || !c) return;
    const rect = el.getBoundingClientRect();
    if (rect.width === 0 || rect.height === 0) return;
    const aspect = rect.width / rect.height;
    const t = state.clock.elapsedTime;

    // pointer in the view's NDC, or null when it's outside the hero
    let px = 0;
    let py = 0;
    let inside = false;
    const p = pointer.current;
    if (p && p.x >= rect.left && p.x <= rect.right && p.y >= rect.top && p.y <= rect.bottom) {
      inside = true;
      px = ((p.x - rect.left) / rect.width) * 2 - 1;
      py = -(((p.y - rect.top) / rect.height) * 2 - 1);
    }

    // parallax: the camera leans toward the pointer, so near stickers slide further than far ones
    const tx = inside && !reduce ? px * 1.3 : 0;
    const ty = inside && !reduce ? py * 0.9 : 0;
    c.position.x = THREE.MathUtils.damp(c.position.x, tx, 3, dt);
    c.position.y = THREE.MathUtils.damp(c.position.y, ty, 3, dt);
    c.lookAt(0, 0, 0);

    let hit = -1;
    let hitZ = -Infinity;
    placed.forEach((s, i) => {
      const g = groups.current[i];
      if (!g) return;
      const halfH = (CAM_Z - s.z) * TAN;
      const drift = reduce ? 0 : 1;
      g.position.set(
        s.nx * halfH * aspect * 0.9 + drift * Math.sin(t * 0.35 + s.phase) * 0.22,
        s.ny * halfH * 0.84 + drift * Math.cos(t * 0.42 + s.phase * 1.3) * 0.26,
        s.z
      );
      g.rotation.z = s.tilt + drift * Math.sin(t * 0.25 + s.phase) * 0.08;
      if (!inside || reduce) return;
      v3.copy(g.position).project(c);
      const radius = (2.6 * s.scale * 0.85) / ((CAM_Z - s.z) * TAN);
      const dx = (v3.x - px) * aspect;
      const dy = v3.y - py;
      if (dx * dx + dy * dy < radius * radius && s.z > hitZ) {
        hit = i;
        hitZ = s.z;
      }
    });
    if (hit !== hoveredRef.current) {
      hoveredRef.current = hit;
      setHovered(hit);
    }
  });

  return (
    <>
      <PerspectiveCamera ref={cam} makeDefault position={[0, 0, CAM_Z]} fov={FOV} />
      <hemisphereLight args={["#ffffff", "#8890a0", 1.6]} />
      <directionalLight position={[-4, 6, 8]} intensity={2.2} />
      {placed.map((s, i) => (
        <group key={i} ref={(g) => void (groups.current[i] = g)} scale={s.scale}>
          <VoxelSticker
            pattern={s.pattern}
            colors={s.colors}
            motion={reduce ? "still" : "flutter"}
            peel={hovered === i ? 1 : 0}
          />
        </group>
      ))}
    </>
  );
}

"use client";
import * as React from "react";
import * as THREE from "three";
import { useFrame } from "@react-three/fiber";
import { defaultPalette, type PixelPattern } from "@/components/ui/three/patterns";

/**
 * VoxelSticker — a pixel pattern extruded into 3D cubes over a white kiss-cut backing
 * (the pattern dilated by one cell), so it reads as the same die-cut sticker as the DOM kit.
 * Use inside a drei <View/> (see <Sticker3D/>) or any R3F scene.
 */
export interface VoxelStickerProps {
  pattern: PixelPattern;
  colors?: Record<string, string>;
  /** "flutter" idles gently; "spin" turns slowly; "still" holds. */
  motion?: "flutter" | "spin" | "still";
  /** 0..1 — how far the sticker peels toward the viewer (drive from hover). */
  peel?: number;
  depth?: number;
}

function cellsOf(pattern: PixelPattern) {
  const h = pattern.length;
  const w = Math.max(...pattern.map((r) => r.length));
  const cells: { x: number; y: number; key: string }[] = [];
  pattern.forEach((row, y) =>
    [...row].forEach((key, x) => {
      if (key !== "." && key !== " ") cells.push({ x: x - (w - 1) / 2, y: (h - 1) / 2 - y, key });
    })
  );
  // kiss-cut backing: dilate occupied cells by one in 8 directions
  const occ = new Set(cells.map((c) => `${c.x},${c.y}`));
  const back = new Set<string>();
  cells.forEach(({ x, y }) => {
    for (let dx = -1; dx <= 1; dx++) for (let dy = -1; dy <= 1; dy++) back.add(`${x + dx},${y + dy}`);
  });
  return { cells, back: [...back].map((k) => k.split(",").map(Number) as [number, number]), w, h, occ };
}

const tmp = new THREE.Object3D();

export function VoxelSticker({ pattern, colors, motion = "flutter", peel = 0, depth = 0.55 }: VoxelStickerProps) {
  const palette = { ...defaultPalette, ...colors };
  const { cells, back, w, h } = React.useMemo(() => cellsOf(pattern), [pattern]);
  const group = React.useRef<THREE.Group>(null);
  const front = React.useRef<THREE.InstancedMesh>(null);
  const backing = React.useRef<THREE.InstancedMesh>(null);
  const reduce = React.useMemo(
    () => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches,
    []
  );

  React.useLayoutEffect(() => {
    const color = new THREE.Color();
    cells.forEach((c, i) => {
      tmp.position.set(c.x, c.y, depth / 2);
      tmp.updateMatrix();
      front.current!.setMatrixAt(i, tmp.matrix);
      front.current!.setColorAt(i, color.set(palette[c.key] ?? "#ff3d8b"));
    });
    front.current!.instanceMatrix.needsUpdate = true;
    if (front.current!.instanceColor) front.current!.instanceColor.needsUpdate = true;
    back.forEach(([x, y], i) => {
      tmp.position.set(x, y, -0.06);
      tmp.updateMatrix();
      backing.current!.setMatrixAt(i, tmp.matrix);
    });
    backing.current!.instanceMatrix.needsUpdate = true;
  }, [cells, back, depth, palette]);

  const peelRef = React.useRef(0);
  useFrame((state, dt) => {
    const g = group.current;
    if (!g) return;
    const t = state.clock.elapsedTime;
    peelRef.current = THREE.MathUtils.damp(peelRef.current, peel, 8, dt);
    const p = peelRef.current;
    const idle = reduce || motion === "still" ? 0 : 1;
    const spin = motion === "spin" && !reduce ? t * 0.6 : 0;
    g.rotation.y = spin + idle * (motion === "flutter" ? Math.sin(t * 1.2) * 0.28 : 0) + p * -0.35;
    g.rotation.x = idle * (motion === "flutter" ? Math.sin(t * 1.7) * 0.12 : 0) - 0.12 + p * 0.45;
    g.rotation.z = -0.05 + p * 0.06;
    g.position.z = p * 1.2;
  });

  const scale = 1 / Math.max(w + 2, h + 2);
  return (
    <group ref={group} scale={scale * 5.2}>
      <instancedMesh ref={backing} args={[undefined, undefined, back.length]}>
        <boxGeometry args={[1, 1, 0.12]} />
        <meshStandardMaterial color="#ffffff" roughness={0.55} />
      </instancedMesh>
      <instancedMesh ref={front} args={[undefined, undefined, cells.length]}>
        <boxGeometry args={[0.98, 0.98, depth]} />
        <meshStandardMaterial roughness={0.32} metalness={0.02} />
      </instancedMesh>
    </group>
  );
}

"use client";
import * as React from "react";
import { View, PerspectiveCamera } from "@react-three/drei";
import { cn } from "@/lib/pixel3d";
import { useStickerCanvas } from "@/components/ui/three/sticker-canvas";
import { VoxelSticker } from "@/components/ui/three/voxel-sticker";
import { patterns, defaultPalette, type PatternName, type PixelPattern } from "@/components/ui/three/patterns";

/**
 * Sticker3D — a real three.js voxel sticker that sits in normal page layout.
 * It peels toward you on hover. Requires <StickerCanvas> somewhere above it.
 * Before the canvas mounts (or with WebGL off) it renders a crisp SVG of the same pattern.
 *
 *   <Sticker3D pattern="heart" className="size-48" />
 *   <Sticker3D pattern={["pp.", ".pp"]} colors={{ p: "#36b8ff" }} motion="spin" />
 */
export interface Sticker3DProps extends React.HTMLAttributes<HTMLDivElement> {
  pattern: PatternName | PixelPattern;
  colors?: Record<string, string>;
  motion?: "flutter" | "spin" | "still";
  label?: string;
}

export function Sticker3D({ pattern, colors, motion = "flutter", label, className, ...props }: Sticker3DProps) {
  const { ready } = useStickerCanvas();
  const grid = typeof pattern === "string" ? patterns[pattern] : pattern;
  const [hover, setHover] = React.useState(false);
  return (
    <div
      role="img"
      aria-label={label ?? (typeof pattern === "string" ? `${pattern} sticker` : "pixel sticker")}
      className={cn("relative aspect-square", className)}
      onPointerEnter={() => setHover(true)}
      onPointerLeave={() => setHover(false)}
      {...props}
    >
      {!ready && <PatternSVG pattern={grid} colors={colors} className="absolute inset-[12%]" />}
      {ready && (
        <View className="absolute inset-0">
          <PerspectiveCamera makeDefault position={[0, 0, 10]} fov={32} />
          <hemisphereLight args={["#ffffff", "#8890a0", 1.6]} />
          <directionalLight position={[-4, 6, 8]} intensity={2.2} />
          <VoxelSticker pattern={grid} colors={colors} motion={motion} peel={hover ? 1 : 0} />
        </View>
      )}
    </div>
  );
}

/** The static, crisp SVG version of a pattern (fallback + usable on its own). */
export function PatternSVG({
  pattern,
  colors,
  className,
}: {
  pattern: PixelPattern;
  colors?: Record<string, string>;
  className?: string;
}) {
  const palette = { ...defaultPalette, ...colors };
  const w = Math.max(...pattern.map((r) => r.length));
  const h = pattern.length;
  return (
    <svg viewBox={`-1 -1 ${w + 2} ${h + 2}`} className={cn("pixel-icon", className)} aria-hidden>
      {pattern.map((row, y) =>
        [...row].map((k, x) =>
          k === "." || k === " " ? null : (
            <rect key={`b${x}-${y}`} x={x - 1} y={y - 1} width={3} height={3} fill="#fff" />
          )
        )
      )}
      {pattern.map((row, y) =>
        [...row].map((k, x) =>
          k === "." || k === " " ? null : <rect key={`${x}-${y}`} x={x} y={y} width={1} height={1} fill={palette[k] ?? "#ff3d8b"} />
        )
      )}
    </svg>
  );
}

"use client";
import * as React from "react";
import { Canvas } from "@react-three/fiber";
import { View } from "@react-three/drei";

/**
 * StickerCanvas — the ONE shared WebGL canvas for a page.
 * Browsers cap WebGL contexts (~16), so every <Sticker3D/> renders into this canvas
 * through drei <View/>, scissored to its own DOM box. Wrap your app (or layout) once:
 *
 *   <StickerCanvas>{children}</StickerCanvas>
 *
 * The canvas is fixed, transparent and pointer-events:none; events come from document.body.
 * It mounts after first paint (never blocks LCP) and stays off under reduced motion
 * when `respectReducedMotion` is true (3D stickers then show their static SVG fallback).
 */
const StickerCanvasContext = React.createContext<{ ready: boolean }>({ ready: false });
export const useStickerCanvas = () => React.useContext(StickerCanvasContext);

export interface StickerCanvasProps {
  children: React.ReactNode;
  respectReducedMotion?: boolean;
}

export function StickerCanvas({ children, respectReducedMotion = false }: StickerCanvasProps) {
  const [ready, setReady] = React.useState(false);
  const [eventSource, setEventSource] = React.useState<HTMLElement | null>(null);

  React.useEffect(() => {
    if (respectReducedMotion && window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const start = () => {
      setEventSource(document.body);
      setReady(true);
    };
    const w = window as Window & { requestIdleCallback?: (cb: () => void) => number };
    if (w.requestIdleCallback) w.requestIdleCallback(start);
    else setTimeout(start, 1);
  }, [respectReducedMotion]);

  const canvas = ready && eventSource && (
        <Canvas
          eventSource={eventSource}
          eventPrefix="client"
          flat
          dpr={[1, 2]}
          gl={{ antialias: true, alpha: true }}
          style={{ position: "fixed", inset: 0, width: "100%", height: "100%", pointerEvents: "none", zIndex: 30 }}
          aria-hidden
        >
          <View.Port />
        </Canvas>
  );

  return (
    <StickerCanvasContext.Provider value={{ ready }}>
      {children}
      {canvas}
    </StickerCanvasContext.Provider>
  );
}
